/* A record of every price Storelib corrects for a creator (currency round AO). scripts/price-restore.mjs undoes the 4.6 multiplication of supabase/sql/RUN_CURRENCY_RON.sql only for a product its own order proves was multiplied (scripts/price-audit.mjs), and writes one row here BEFORE each change: which product or option, which field, the value before and after, the proof, and who approved it. An undo (--undo) reads these rows back. Orders and payments are never touched. Admin only: row level security on, no policy for anyone but the service role. Only adds a table; safe to run again. */
CREATE TABLE IF NOT EXISTS public.price_corrections (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), batch text NOT NULL CHECK (length(batch) BETWEEN 6 AND 80), product_id uuid NOT NULL, variant_id uuid, field text NOT NULL CHECK (field IN ('price_cents', 'pwyw_min_price_cents', 'pwyw_suggested_price_cents', 'compare_at_cents', 'variant_price_cents')), before_cents bigint NOT NULL CHECK (before_cents >= 0), after_cents bigint NOT NULL CHECK (after_cents >= 0), proof text NOT NULL CHECK (length(proof) BETWEEN 10 AND 600), approved_by text NOT NULL CHECK (length(approved_by) BETWEEN 2 AND 120), applied_at timestamptz, undone_at timestamptz);
CREATE INDEX IF NOT EXISTS price_corrections_product ON public.price_corrections (product_id, created_at DESC);
ALTER TABLE public.price_corrections ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_corrections FROM anon, authenticated;
notify pgrst, 'reload schema';
